changeSet.sql:
CREATE TABLE site_about (
 id INTEGER PRIMARY KEY CHECK(id=1), title VARCHAR(160) NOT NULL, lead VARCHAR(1000) NOT NULL,
 body VARCHAR(20000) NOT NULL, signature VARCHAR(160) NOT NULL, link_label VARCHAR(120) NOT NULL,
 photo_alt VARCHAR(255) NOT NULL, version BIGINT NOT NULL DEFAULT 0
);
CREATE TABLE site_about_images (
 slot VARCHAR(16) PRIMARY KEY CHECK(slot IN ('portrait','development','library')),
 enabled BOOLEAN NOT NULL DEFAULT TRUE, data BYTEA
);
INSERT INTO site_about(id,title,lead,body,signature,link_label,photo_alt) VALUES (1,'О магазине','«Переплёт» начался с любопытства и желания освоить новое.','Большую часть своей профессиональной жизни я посвятил юриспруденции. В сорок лет решил начать изучать программирование на Java. Примерно через полгода появился замысел первого самостоятельного проекта: создать веб-приложение, в котором можно соединить любовь к книгам, интерес к технологиям и собственное представление об эстетике.

Так постепенно складывался этот книжный магазин. Сначала появилась его внутренняя часть: работа с данными, пользователями, каталогом и заказами. За каждой возможностью стояли изучение, попытки, ошибки и поиск решения. Когда основная логика заработала, захотелось придать ей видимую форму. Следующим этапом стал интерфейс: страницы, обложки, шрифты, свет и тени книжных полок. Приложение обрело облик, и его стало возможно показать другим.

Название «Переплёт» оказалось созвучно этой истории. Здесь встретились право и программирование, привычная профессия и новое увлечение, содержание книги и искусство её оформления.

У проекта нет коммерческой цели. Облик книжного магазина помогает наглядно показать, как устроено полноценное веб-приложение и что можно создать, последовательно осваивая разработку на Java. При этом мне важно, чтобы результат был полезен: уже сейчас здесь можно найти и скачать некоторые книги, выбрать чтение и познакомиться с рекомендациями.

«Переплёт» продолжает развиваться. Я буду совершенствовать приложение, дополнять библиотеку и расширять возможности сайта. В нём ещё многое предстоит сделать, и эта работа остаётся частью моего обучения.

Для меня этот проект стал личным опытом освоения нового дела. Буду рад, если для вас он станет местом, где найдётся нужная книга, интересная мысль или повод начать что-то своё.','Андрей Анцибор','На книжную полку ↗','Андрей Анцибор, автор проекта «Переплёт»');
INSERT INTO site_about_images(slot) VALUES ('portrait'),('development'),('library');
